/**
 * Every checked Wikimedia Commons file in config/images.yaml, for card thumbnails and heroes.
 * Generated by scripts/build_image_library.py; do not edit by hand. Each file's page was read
 * (creator, license); each shows a place or subject, never a news event, and is labelled.
 */
export interface LibraryImage {
  id: string
  /** Wikimedia thumbnail URL with {width}: 500, 960 or 1920. */
  url: string
  filePage: string
  creator: string
  credit: string
  license: string
  licenseUrl: string
  alt: string
  caption: string
  position: string
  country: string | null
  cities: number[]
  sectors: string[]
  /** A topic photo is used only when the headline contains one of these. */
  headlineWords: string[]
}

